head.script:
scwin.gridView1 = "";
scwin.gridView2 = "";
scwin.setGridView1 = function(id) {
    scwin.gridView1 = id;
}
scwin.setGridView2 = function(id) {
    scwin.gridView2 = id;
}
scwin.multiDown = function(grid1id, grid2id) {
    var options = {
        common: {
            fileName: "user.xls",
            showProcess: true,
            printSet: {
                landScape: "true",
                fitToPage: "true",
                fitWidth: "4",
                fitHeight: "333",
                scale: "222"
            }
        },
        excelInfo: [{
                gridId: grid1id,
                sheetName: "첫번째 sheet",
                type: "1",
                removeColumns: "",
                foldColumns: "2",
                startRowIndex: 3,
                startColumnIndex: 0,
                headerColor: "#DBEEF3",
                bodyColor: "#92CDDC",
                //dataProvider : "com.provider.SampleProvider", 
                //providerRequestXml : "<data><actionId>A001</actionId></data>", 
                infoArr: [{
                    rowIndex: 1,
                    colIndex: 3,
                    rowSpan: 1,
                    colSpan: 2,
                    text: "데이터표시",
                    textAlign: "center"
                }]
            },
            {
                gridId: grid2id,
                sheetName: "두번째 sheet",
                type: "1",
                removeColumns: "",
                foldColumns: "2",
                startRowIndex: 3,
                startColumnIndex: 0,
                headerColor: "#DBEEF3",
                bodyColor: "#92CDDC",
                //dataProvider : "com.provider.SampleProvider", 
                //providerRequestXml : "<data><actionId>A002</actionId></data>", 
                infoArr: [{
                    rowIndex: 1,
                    colIndex: 3,
                    rowSpan: 1,
                    colSpan: 2,
                    text: "데이터표시",
                    textAlign: "center"
                }]
            }
        ]
    };
    WebSquare.util.multipleExcelDownload(options);
}
scwin.trigger1_onclick = function(e) {
    scwin.multiDown(scwin.gridView1, scwin.gridView2);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
